import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find features with significant association (p < 0.05)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'expression':
            t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
            if p_val < 0.05:
                sig_features.append((fid, abs(t_stat)))

    # Sort by t-statistic magnitude
    sig_features.sort(key=lambda x: x[1], reverse=True)

    # Remove near-duplicates (correlated pairs)
    correlated_pairs = set()
    for pair in [('UKIG4', 'RHH16'), ('UKIG4', 'MBPM16L'), ('UKIG4', 'GDVD19'),
                 ('EHJ3', 'UKIG4'), ('KXS1P', 'CON18P'), ('UKIG4', 'XRD6'),
                 ('UKIG4', 'HPUN5'), ('RHH16', 'GDVD19'), ('XRD6', 'DZYB2'),
                 ('MBPM16L', 'RHH16'), ('MBPM16L', 'GDVD19'), ('RHH16', 'HPUN5'),
                 ('EHJ3', 'RHH16'), ('UKIG4', 'SFOM7L'), ('KZZ10', 'GDVD19'),
                 ('XRD6', 'RHH16'), ('UKIG4', 'KXS1P'), ('EHJ3', 'MBPM16L'),
                 ('EHJ3', 'GDVD19'), ('SFOM7L', 'RHH16')]:
        correlated_pairs.add(pair)

    # Build driver list avoiding near-duplicates
    drivers = []
    used = set()
    for fid, _ in sig_features[:10]:  # Check top 10
        if fid in used:
            continue
        # Check if this feature is correlated with any already selected
        is_correlated = False
        for d in drivers:
            if (d, fid) in correlated_pairs or (fid, d) in correlated_pairs:
                is_correlated = True
                break
        if not is_correlated:
            drivers.append(fid)
            used.add(fid)
            if len(drivers) >= MAX_DRIVERS:
                break

    # If we have 2+ drivers, look for interaction terms
    if len(drivers) >= 2:
        # Try pairwise interactions
        best_product = None
        best_p = 1.0
        for i in range(len(drivers)):
            for j in range(i+1, len(drivers)):
                a, b = drivers[i], drivers[j]
                if (a, b) in correlated_pairs or (b, a) in correlated_pairs:
                    continue  # Skip correlated pairs
                # Compute product
                col_a = feats.column(a)
                col_b = feats.column(b)
                prod = feats.x[:, col_a] * feats.x[:, col_b]

                # Test significance of product using t-test
                t_stat, p_val = stats.ttest_ind(prod[feats.y==1], prod[feats.y==0])
                if p_val < best_p:
                    best_p = p_val
                    best_product = (a, b)

        if best_product and best_p < 0.05:
            return Design(
                drivers=drivers[:1],
                columns=[drivers[0]],
                products=[best_product],
                loadings={}
            )

    # No strong interaction found, return simple model
    if drivers:
        return Design(
            drivers=drivers[:1],
            columns=[drivers[0]],
            products=[],
            loadings={}
        )

    # No mechanism case
    return Design(drivers=(), columns=[], products=[], loadings={})

